<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{api}from'../api';import MetricCard from'../components/MetricCard.vue';const rows=ref<any[]>([]),health=ref<any>({}),loading=ref(true),error=ref('');const devices=computed(()=>rows.value.reduce((n,x)=>n+Number(x.devices_used||0),0));const active=computed(()=>rows.value.filter(x=>x.status==='active').length);const expiring=computed(()=>rows.value.filter(x=>{if(!x.subscription_expires_at)return false;const days=(new Date(x.subscription_expires_at).getTime()-Date.now())/86400000;return days>=0&&days<=30}).length);async function load(){loading.value=true;error.value='';try{[rows.value,health.value]=await Promise.all([api('/tk-api/enterprise/platform/tenants').then(x=>x.tenants),api('/api/v1/health')])}catch(e:any){error.value=e.message}finally{loading.value=false}}onMounted(load);</script>
<template><div class="page-stack"><div v-if="loading" class="panel state-inline">正在汇总平台状态……</div><div v-else-if="error" class="panel state-inline error"><b>暂时无法获取平台状态</b><span>{{error}}</span><button @click="load">立即重试</button></div><template v-else><section class="panel platform-summary"><header><div><span class="eyebrow">PLATFORM HEALTH</span><h2>{{health.status==='ok'?'平台运行正常':'平台需要检查'}}</h2><p>当前状态由健康接口实时返回，不使用模拟告警数据。</p></div><span :class="['health-badge',health.status!=='ok'?'warning':'']">{{health.status==='ok'?'服务正常':'状态降级'}}</span></header></section><section class="metrics-grid platform-metrics"><MetricCard label="企业总数" :value="rows.length" tone="blue"/><MetricCard label="正常企业" :value="active" tone="green"/><MetricCard label="平台设备" :value="devices" tone="violet"/><MetricCard label="30天内到期" :value="expiring" tone="amber"/><MetricCard label="服务版本" :value="health.version||'-'" tone="blue"/><MetricCard label="数据库 / 资源" :value="`${health.database||'-'} / ${health.admin_assets||'-'}`" :tone="health.status==='ok'?'green':'red'"/></section><section class="panel"><header class="panel-head"><div><h3>企业健康</h3><p>优先关注到期、停用和设备额度接近上限的企业。</p></div></header><div class="responsive-table"><table><thead><tr><th>企业</th><th>套餐</th><th>状态</th><th>设备</th><th>到期时间</th><th>建议</th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td><b>{{x.name}}</b><small>{{x.tenant_code}}</small></td><td>{{x.plan_code}}</td><td>{{x.status==='active'?'正常':'已停用'}}</td><td>{{x.devices_used}} / {{x.device_limit}}</td><td>{{x.subscription_expires_at?.slice(0,10)||'未设置'}}</td><td>{{x.status!=='active'?'企业已停用':x.devices_used>=x.device_limit?'设备额度已满':'无需处理'}}</td></tr></tbody></table></div><div v-if="!rows.length" class="empty-state">还没有开通企业。前往“企业管理”创建首个企业。</div></section></template></div></template>
